section(L["Farm"], function()
    local rejRE = rem("EggHitRejected")
    if rejRE then track(rejRE.OnClientEvent:Connect(function() S.rejects = S.rejects + 1 end)) end

    local function eggZone(egg)
        local z = egg:GetAttribute("ZoneIndex")
        if type(z) == "number" then return z end
        local m = egg.Parent and egg.Parent.Parent and egg.Parent.Parent.Parent
        return m and tonumber(tostring(m.Name):match("%d+")) or 0
    end
    local function eggLive(egg)
        return egg and egg.Parent ~= nil and not egg:GetAttribute("Broken") and not egg:GetAttribute("Hatching") and not egg:GetAttribute("Despawning") and num(egg:GetAttribute("Health")) > 0
    end
    S.eggZone, S.eggLive = eggZone, eggLive

    local function currentDelay()
        if on("bs_autohit") then return S.hitDelay end
        return math.max(0.05, (Opt.bs_hitdelay and Opt.bs_hitdelay.Value) or 0.5)
    end
    local function breakTime(egg)
        return math.ceil(num(egg:GetAttribute("Health")) / pickaxeDamage()) * currentDelay()
    end
    S.breakTime = breakTime

    local function bestEgg()
        local zones = multiSet("bs_zones")
        local rar = multiSet("bs_eggrarity")
        local maxT = zones and math.huge or 60
        local r = root()
        local here = r and r.Position or Vector3.zero
        local best, br, bt, bd
        S.tooSlow = nil
        for _, egg in ipairs(CollectionService:GetTagged("BreakableEgg")) do
            if egg:IsA("BasePart") and eggLive(egg) then
                local z = eggZone(egg)
                local lbl = ZONE_LABELS[z]
                local rarity = eggRarity(egg)
                if zoneAllowed(z) and (not zones or (lbl and zones[lbl])) and (not rar or rar[rarity]) then
                    local t = breakTime(egg)
                    if t > maxT and (not S.tooSlow or t < S.tooSlow.t) then
                        S.tooSlow = { t = t, hp = num(egg:GetAttribute("Health")), zone = z }
                    end
                    if t <= maxT then
                        local rk = RARITY_RANK[rarity] or 0
                        local d = (egg.Position - here).Magnitude
                        local better
                        if not best then
                            better = true
                        elseif zones then
                            better = t < bt or (t == bt and (rk > br or (rk == br and d < bd)))
                        else
                            better = rk > br or (rk == br and (t < bt or (t == bt and d < bd)))
                        end
                        if better then best, br, bt, bd = egg, rk, t, d end
                    end
                end
            end
        end
        return best, bt
    end

    local function promptFor(model)
        local ok, pos = pcall(function() return model:GetPivot().Position end)
        if not ok then return nil end
        local best, bd
        for _, d in ipairs(workspace:GetChildren()) do
            if d.Name == "PromptAnchor" and d:IsA("BasePart") then
                local p = d:FindFirstChild("StealPrompt")
                if p and p:IsA("ProximityPrompt") then
                    local dist = (d.Position - pos).Magnitude
                    if dist < 25 and (not bd or dist < bd) then best, bd = p, dist end
                end
            end
        end
        if not best then
            for _, d in ipairs(model:GetDescendants()) do
                if d:IsA("ProximityPrompt") then return d end
            end
        end
        return best
    end

    local function pickups(filtered)
        local out = {}
        local folder = workspace:FindFirstChild("AnimalPickups")
        if not folder then return out end
        local rar = filtered and multiSet("bs_rarity") or nil
        local brk = filtered and multiSet("bs_bracket") or nil
        local minV = filtered and (tonumber(Opt.bs_minvalue and Opt.bs_minvalue.Value) or 0) or 0
        local zones = filtered and multiSet("bs_zones") or nil
        local now = workspace:GetServerTimeNow()
        for _, m in ipairs(folder:GetChildren()) do
            if m:IsA("Model") and m:GetAttribute("AnimalName") then
                local rarity = m:GetAttribute("Rarity") or "?"
                local bracket = m:GetAttribute("WeightBracket")
                if bracket == nil or bracket == "" then bracket = "Normal" end
                local despawn = m:GetAttribute("DespawnAtServerTime")
                local zi = tonumber(tostring(m:GetAttribute("ZoneId") or ""):match("%d+"))
                local value = animalValue(m)
                local outOfZone = zones and zi and not zones[ZONE_LABELS[zi] or ""]
                local blocked = filtered and ((S.skipPick[m] and S.skipPick[m] > os.clock()) or (zi and not (zoneAllowed(zi))) or outOfZone or value < minV)
                if not blocked and (not rar or rar[rarity]) and (not brk or brk[bracket]) and not (type(despawn) == "number" and despawn - now < 1) then
                    out[#out + 1] = { m = m, rank = RARITY_RANK[rarity] or 0, br = BRACKET_RANK[bracket] or 1, kg = num(m:GetAttribute("WeightKg")), value = value }
                end
            end
        end
        table.sort(out, function(a, b)
            if a.value ~= b.value then return a.value > b.value end
            if a.rank ~= b.rank then return a.rank > b.rank end
            return a.kg > b.kg
        end)
        return out
    end
    S.pickups = pickups

    local function bank()
        local cf = bankCF()
        if not cf then return false end
        tp(cf)
        return waitUntil(function() return carrying() == 0 end, 4)
    end
    S.bank = bank

    local function steal(m, patience)
        local p
        waitUntil(function() p = promptFor(m) return p ~= nil or not m.Parent end, 2)
        if not p or not p.Parent then
            S.skipPick[m] = os.clock() + 15
            return false
        end
        if not p.Enabled and carrying() < capacity() then
            S.last = "Last: waiting for animal to unlock"
            tp(p.Parent.Position + Vector3.new(0, 2, 0))
            if not waitUntil(function() return p.Enabled or not m.Parent or not p.Parent end, patience or 3) or not m.Parent then
                S.skipPick[m] = os.clock() + 4
                S.last = "Last: animal still locked, skipping"
                return false
            end
        end
        local before = carrying()
        local value = animalValue(m)
        for _ = 1, 4 do
            if not RUNNING or not m.Parent or not p.Parent then return false end
            tp(p.Parent.Position + Vector3.new(0, 2, 0))
            if p.HoldDuration > 0 then p.HoldDuration = 0 end
            task.wait(0.1)
            triggerPrompt(p)
            if waitUntil(function() return carrying() > before end, 1) then
                S.stolen = S.stolen + 1
                S.last = string.format("Last: stole %s (+%s/s)", tostring(m:GetAttribute("AnimalName") or "animal"), abbrev(value))
                return true
            end
        end
        S.skipPick[m] = os.clock() + 15
        S.last = "Last: couldn't grab, trying another"
        return false
    end
    S.steal = steal

    local function equipPickaxe()
        local c = lp.Character
        local h = hum()
        if not (c and h) then return end
        if c:FindFirstChild("Pickaxe") then return end
        local bp = lp:FindFirstChildOfClass("Backpack")
        local tool = bp and bp:FindFirstChild("Pickaxe")
        if tool and tool:IsA("Tool") then pcall(function() h:EquipTool(tool) end) end
    end

    local function breakEgg(egg)
        local hit = rem("EggHitRequest")
        if not hit then return false end
        local half = math.max(egg.Size.X, egg.Size.Z) / 2
        local spot = egg.Position + Vector3.new(half + 2.5, 0, 0)
        local look = CFrame.lookAt(spot, Vector3.new(egg.Position.X, spot.Y, egg.Position.Z))
        local t0 = os.clock()
        local existed = {}
        local folder = workspace:FindFirstChild("AnimalPickups")
        if folder then for _, m in ipairs(folder:GetChildren()) do existed[m] = true end end
        local eta = breakTime(egg)
        S.target = tostring(egg:GetAttribute("EggType") or "Egg") .. (eta > 60 and ("  ~" .. fmtDur(eta)) or "")
        tp(look)
        task.wait(0.15)
        local sent, rej0 = 0, S.rejects
        local lastLook = os.clock()
        while RUNNING and on("bs_farm") and eggLive(egg) and os.clock() - t0 < 60 do
            if carrying() > 0 and lp:GetAttribute("BeingChased") ~= nil then break end
            if on("bs_steal") and carrying() < capacity() and os.clock() - lastLook > 0.75 then
                lastLook = os.clock()
                for _, it in ipairs(pickups(true)) do
                    local p = promptFor(it.m)
                    if p and p.Enabled then S.target = "" return false end
                end
            end
            equipPickaxe()
            local r = root()
            if r and (r.Position - spot).Magnitude > 4 then tp(look) end
            pcall(hit.FireServer, hit, egg)
            sent = sent + 1
            if on("bs_autohit") and sent % 8 == 0 then
                local rejected = S.rejects - rej0
                rej0 = S.rejects
                if rejected >= 2 then
                    S.hitDelay = math.min(1, S.hitDelay + 0.05)
                elseif rejected == 0 then
                    S.hitDelay = math.max(0.05, S.hitDelay - 0.02)
                end
            end
            task.wait(currentDelay())
        end
        S.target = ""
        if eggLive(egg) then return false end
        S.broken = S.broken + 1
        local pos = egg.Position
        local drop
        S.last = "Last: hatching..."
        waitUntil(function()
            local f = workspace:FindFirstChild("AnimalPickups")
            if not f then return false end
            local bestD
            for _, m in ipairs(f:GetChildren()) do
                if not existed[m] and m:IsA("Model") and m:GetAttribute("AnimalName") then
                    local ok, pv = pcall(function() return m:GetPivot().Position end)
                    local d = ok and (pv - pos).Magnitude or math.huge
                    if d < 60 and (not bestD or d < bestD) then drop, bestD = m, d end
                end
            end
            return drop ~= nil
        end, 10)
        if drop then
            steal(drop, 8)
        else
            S.last = "Last: no animal dropped"
        end
        return true
    end

    local function farmCycle()
        if not root() or lp:GetAttribute("Jailed") then return end
        local c, cap = carrying(), capacity()
        if c > 0 and (c >= cap or on("bs_bankeach") or lp:GetAttribute("BeingChased") ~= nil) then
            bank()
            return
        end
        if on("bs_steal") then
            for _, it in ipairs(pickups(true)) do
                if it.m.Parent then
                    S.busy = true
                    steal(it.m)
                    S.busy = false
                    return
                end
            end
        end
        local egg = bestEgg()
        if egg then
            S.busy = true
            breakEgg(egg)
            S.busy = false
        elseif carrying() > 0 then
            bank()
        elseif S.tooSlow then
            local need
            local hitsWanted = math.max(1, 60 / currentDelay())
            for _, tier in ipairs((M.Pickaxe and M.Pickaxe.Tiers) or {}) do
                if num(tier.Damage) * hitsWanted >= S.tooSlow.hp then need = tier break end
            end
            S.last = string.format("Fastest egg: %s\nNeed %s", fmtDur(S.tooSlow.t), need and tostring(need.Name) or "a better pickaxe")
        else
            S.last = "Last: no eggs fit your filters"
        end
    end

    local function grabCycle()
        if not root() or lp:GetAttribute("Jailed") then return end
        local c, cap = carrying(), capacity()
        if c > 0 and (c >= cap or on("bs_bankeach") or lp:GetAttribute("BeingChased") ~= nil) then
            bank()
            return
        end
        for _, it in ipairs(pickups(true)) do
            if it.m.Parent then
                S.busy = true
                steal(it.m)
                S.busy = false
                return
            end
        end
        if carrying() > 0 then bank() end
    end


    local Farm = Tabs.Farm:AddLeftGroupbox(L["Auto Farm"], "egg")
    Farm:AddToggle("bs_farm", { Text = L["Auto Break & Steal"], Default = false, Tooltip = L["Breaks eggs, grabs the animals and banks them."] })
    Farm:AddToggle("bs_bankeach", { Text = L["Bank After Each Animal"], Default = true, Tooltip = L["Safer. Off = fill your satchel first."] })
    Farm:AddToggle("bs_locked", { Text = L["Include Higher Zones"], Default = true, Tooltip = L["Zones above your Speed. Guards are faster there."] })
    Farm:AddToggle("bs_autohit", { Text = L["Auto Hit Speed"], Default = true, Tooltip = L["Finds the fastest hit speed that still counts."] })
    local HitDep = Farm:AddDependencyBox()
    HitDep:AddSlider("bs_hitdelay", { Text = L["Hit Delay"], Default = 0.5, Min = 0.05, Max = 1, Rounding = 2, Suffix = "s" })
    pcall(function() HitDep:SetupDependencies({ { Toggles.bs_autohit, false } }) end)
    Farm:AddDivider()
    Farm:AddDropdown("bs_zones", { Values = ZONE_LABELS, Default = {}, Multi = true, AllowNull = true, Text = L["Zones"], Tooltip = L["Leave empty for all."] })
    Farm:AddDropdown("bs_eggrarity", { Values = RARITIES, Default = {}, Multi = true, AllowNull = true, Text = L["Egg Rarities"], Tooltip = L["Leave empty for all. Best rarity is broken first."] })
    Farm:AddButton({ Text = L["Clear Filters"], Func = function()
        for _, k in ipairs({ "bs_zones", "bs_eggrarity", "bs_rarity", "bs_bracket" }) do pcall(function() Opt[k]:SetValue({}) end) end
        pcall(function() Opt.bs_minvalue:SetValue("0") end)
    end })
    Farm:AddDivider()
    Farm:AddButton({ Text = L["Bank Now"], Func = function() task.spawn(bank) end })
    local status = Farm:AddLabel(L["Idle"], true)

    local Grab = Tabs.Farm:AddRightGroupbox(L["Grab Hatched Animals"], "crosshair")
    Grab:AddToggle("bs_steal", { Text = L["Grab Any Hatched Animal"], Default = true, Tooltip = L["Takes the most valuable animals lying around, including other players' hatches. Works without Auto Break too."] })
    Grab:AddInput("bs_minvalue", { Default = "0", Numeric = true, Finished = true, Text = L["Min Cash/s"], Placeholder = L["0 = any"] })
    Grab:AddDropdown("bs_rarity", { Values = RARITIES, Default = {}, Multi = true, AllowNull = true, Text = L["Animal Rarities"], Tooltip = L["Leave empty for all."] })
    Grab:AddDropdown("bs_bracket", { Values = BRACKETS, Default = {}, Multi = true, AllowNull = true, Text = L["Animal Size"], Tooltip = L["Leave empty for all."] })
    local grabStatus = Grab:AddLabel(L["Best nearby: -"], true)

    task.spawn(function()
        while RUNNING do
            if on("bs_farm") then
                pcall(farmCycle)
                S.busy = false
            elseif on("bs_steal") and not S.busy then
                pcall(grabCycle)
                S.busy = false
            end
            task.wait(0.05)
        end
    end)
    local function clip(s, n)
        s = tostring(s or "")
        return #s > n and (s:sub(1, n - 2) .. "..") or s
    end
    task.spawn(function()
        while RUNNING do
            pcall(function()
                local lines = { string.format("Stolen %d  ·  Bag %d/%d", S.stolen, carrying(), capacity()) }
                if lp:GetAttribute("Jailed") then
                    lines[#lines + 1] = "Jailed, waiting"
                elseif S.target ~= "" then
                    lines[#lines + 1] = "Breaking " .. clip(S.target, 20)
                elseif S.last ~= "" then
                    for ln in (S.last:gsub("^Last: ", "") .. "\n"):gmatch("(.-)\n") do lines[#lines + 1] = clip(ln, 26) end
                elseif on("bs_farm") then
                    lines[#lines + 1] = "Looking for eggs"
                else
                    lines[#lines + 1] = L["Idle"]
                end
                status:SetText(table.concat(lines, "\n"))
            end)
            pcall(function()
                local list = pickups(true)
                local b = list[1]
                grabStatus:SetText(b and (clip(tostring(b.m:GetAttribute("AnimalName") or "?"), 14) .. "  +" .. abbrev(b.value) .. L["/s  ·  "] .. #list .. L[" ready"]) or L["Nothing to grab"])
            end)
            task.wait(1)
        end
    end)
end)

section("Manual & ESP", function()
    local Manual = Tabs.Farm:AddRightGroupbox(L["Manual Play"], "hand")
    Manual:AddToggle("bs_instant", { Text = L["Instant Steal"], Default = false, Tooltip = L["No hold time on steal prompts."] })
    Manual:AddToggle("bs_aura", { Text = L["Steal Aura"], Default = false, Tooltip = L["Grabs animals near you."] })
    Manual:AddToggle("bs_escape", { Text = L["Auto Escape When Chased"], Default = false, Tooltip = L["Sends you home when chased."] })

    local promptOrig = setmetatable({}, { __mode = "k" })
    local function fixPrompt(p)
        if not (p:IsA("ProximityPrompt") and p.Name == "StealPrompt") then return end
        if on("bs_instant") then
            if promptOrig[p] == nil then promptOrig[p] = p.HoldDuration end
            if p.HoldDuration ~= 0 then p.HoldDuration = 0 end
        elseif promptOrig[p] ~= nil then
            p.HoldDuration = promptOrig[p]
            promptOrig[p] = nil
        end
    end
    local function applyPrompts()
        for _, d in ipairs(workspace:GetDescendants()) do
            if d:IsA("ProximityPrompt") then pcall(fixPrompt, d) end
        end
    end
    track(workspace.DescendantAdded:Connect(function(d)
        if d:IsA("ProximityPrompt") and on("bs_instant") then task.defer(function() pcall(fixPrompt, d) end) end
    end))
    Toggles.bs_instant:OnChanged(function() task.spawn(applyPrompts) end)
    onClean(function() for p, v in pairs(promptOrig) do pcall(function() p.HoldDuration = v end) end end)

    task.spawn(function()
        while RUNNING do
            if on("bs_aura") and not S.busy and not S.farming() and carrying() < capacity() then
                local r = root()
                if r then
                    for _, d in ipairs(workspace:GetChildren()) do
                        if d.Name == "PromptAnchor" and d:IsA("BasePart") and (d.Position - r.Position).Magnitude <= 10 then
                            local p = d:FindFirstChild("StealPrompt")
                            if p and p.Enabled then triggerPrompt(p) end
                        end
                    end
                end
            end
            if on("bs_escape") and not S.busy and carrying() > 0 and lp:GetAttribute("BeingChased") ~= nil then
                S.busy = true
                pcall(S.bank)
                S.busy = false
            end
            task.wait(0.15)
        end
    end)

    local Esp = Tabs.Farm:AddRightGroupbox(L["ESP"], "eye")
    Esp:AddToggle("bs_eggesp", { Text = L["Egg ESP"], Default = false, Tooltip = L["Colored by rarity, with health."] })
    Esp:AddToggle("bs_petesp", { Text = L["Animal ESP"], Default = false, Tooltip = L["Shows hatched animals with rarity and size."] })
    Esp:AddDropdown("bs_esprarity", { Values = RARITIES, Default = {}, Multi = true, AllowNull = true, Text = L["Egg ESP Rarities"], Tooltip = L["Leave empty for all."] })

    local holder = Instance.new("Folder")
    holder.Name = HttpService:GenerateGUID(false)
    local okHui, hui = pcall(function() return gethui and gethui() or game:GetService("CoreGui") end)
    holder.Parent = (okHui and hui) or lp:WaitForChild("PlayerGui")
    onClean(function() pcall(function() holder:Destroy() end) end)
    local tags = {}
    local function partOf(inst)
        if inst:IsA("BasePart") then return inst end
        if inst:IsA("Model") then return inst.PrimaryPart or inst:FindFirstChildWhichIsA("BasePart", true) end
        return nil
    end
    local function tagFor(inst, isEgg)
        local t = tags[inst]
        if t and t.bb.Parent then return t end
        local part = partOf(inst)
        if not part then return nil end
        local bb = Instance.new("BillboardGui")
        bb.Size = UDim2.fromOffset(170, 38)
        bb.StudsOffsetWorldSpace = Vector3.new(0, (isEgg and part.Size.Y / 2 or 2) + 1.5, 0)
        bb.AlwaysOnTop = true
        bb.LightInfluence = 0
        bb.Adornee = part
        bb.Parent = holder
        local tl = Instance.new("TextLabel")
        tl.BackgroundTransparency = 1
        tl.Size = UDim2.fromScale(1, 1)
        tl.Font = Enum.Font.GothamBold
        tl.TextSize = 13
        tl.TextStrokeTransparency = 0.3
        tl.TextColor3 = Color3.new(1, 1, 1)
        tl.Parent = bb
        local mark
        if isEgg then
            mark = Instance.new("BoxHandleAdornment")
            mark.Size = part.Size + Vector3.new(0.3, 0.3, 0.3)
            mark.Transparency = 0.55
            mark.AlwaysOnTop = true
            mark.ZIndex = 1
            mark.Adornee = part
        else
            mark = Instance.new("Highlight")
            mark.FillTransparency = 0.6
            mark.OutlineTransparency = 0
            mark.Adornee = inst
        end
        mark.Parent = holder
        t = { bb = bb, tl = tl, mark = mark, egg = isEgg }
        tags[inst] = t
        return t
    end
    local function dropTag(inst)
        local t = tags[inst]
        if t then pcall(function() t.bb:Destroy() t.mark:Destroy() end) tags[inst] = nil end
    end
    local function colorOf(rarity)
        return RARITY_COLOR[rarity] or Color3.new(1, 1, 1)
    end
    task.spawn(function()
        while RUNNING do
            local seen = {}
            if on("bs_eggesp") then
                local only = multiSet("bs_esprarity")
                for _, egg in ipairs(CollectionService:GetTagged("BreakableEgg")) do
                    if egg:IsA("BasePart") and S.eggLive(egg) then
                        local rarity = eggRarity(egg)
                        if not only or only[rarity] then
                            local t = tagFor(egg, true)
                            if t then
                                seen[egg] = true
                                local c = colorOf(rarity)
                                local locked = not zoneUnlocked(S.eggZone(egg))
                                t.tl.Text = string.format(L["%s%s\n%s  ·  %s / %s HP"], tostring(egg:GetAttribute("EggType") or "Egg"), locked and L["  (locked)"] or "", rarity, abbrev(egg:GetAttribute("Health")), abbrev(egg:GetAttribute("MaxHealth")))
                                t.tl.TextColor3 = c
                                t.mark.Color3 = c
                            end
                        end
                    end
                end
            end
            if on("bs_petesp") then
                for _, it in ipairs(S.pickups(false)) do
                    local t = tagFor(it.m, false)
                    if t then
                        seen[it.m] = true
                        local rarity = tostring(it.m:GetAttribute("Rarity") or "?")
                        local br = it.m:GetAttribute("WeightBracket")
                        local c = colorOf(rarity)
                        t.tl.Text = string.format(L["%s  +%s/s\n%s%s  ·  %s kg"], tostring(it.m:GetAttribute("AnimalName") or "?"), abbrev(it.value), rarity, (br and br ~= "") and ("  " .. br) or "", abbrev(it.kg))
                        t.tl.TextColor3 = c
                        t.mark.FillColor = c
                        t.mark.OutlineColor = c
                    end
                end
            end
            for inst in pairs(tags) do
                if not seen[inst] or not inst.Parent then dropTag(inst) end
            end
            task.wait(0.5)
        end
    end)
end)

section(L["Pets"], function()
    local function animalTools()
        local out = {}
        for _, cont in ipairs({ lp:FindFirstChildOfClass("Backpack"), lp.Character }) do
            for _, t in ipairs(cont and cont:GetChildren() or {}) do
                if t:IsA("Tool") and CollectionService:HasTag(t, "AnimalTool") then out[#out + 1] = t end
            end
        end
        return out
    end
    local function sellSelected()
        local set = multiSet("bs_sellrarity")
        local below = tonumber(Opt.bs_sellbelow and Opt.bs_sellbelow.Value) or 0
        if not set and below <= 0 then return 0 end
        local keepBig = on("bs_keepbig")
        local list = {}
        for _, t in ipairs(animalTools()) do
            local br = t:GetAttribute("WeightBracket")
            local protected = keepBig and type(br) == "string" and br ~= ""
            local match = (set and set[tostring(t:GetAttribute("Rarity") or "")]) or (below > 0 and animalValue(t) < below)
            if match and not protected then list[#list + 1] = t end
        end
        if #list == 0 then return 0 end
        local r = rem("BackpackSellRemote")
        if r and r:IsA("RemoteFunction") then pcall(r.InvokeServer, r, list) end
        return #list
    end

    local P = Tabs.Pets:AddLeftGroupbox(L["Animals"], "paw-print")
    P:AddToggle("bs_equipbest", { Text = L["Auto Equip Best"], Default = false, Tooltip = L["Keeps your best animals on your plot."] })
    P:AddButton({ Text = L["Equip Best Now"], Func = function() fire("PetsInventoryRemote", "EquipBest", nil) end })
    P:AddToggle("bs_index", { Text = L["Auto Claim Index"], Default = false, Tooltip = L["Claims new index rewards."] })
    local petStatus = P:AddLabel(L["Plot: -"], true)

    local Sell = Tabs.Pets:AddRightGroupbox(L["Selling"], "dollar-sign")
    Sell:AddDropdown("bs_sellrarity", { Values = RARITIES, Default = {}, Multi = true, AllowNull = true, Text = L["Rarities To Sell"] })
    Sell:AddInput("bs_sellbelow", { Default = "0", Numeric = true, Finished = true, Text = L["Sell Below Cash/s"], Placeholder = L["0 = off"] })
    Sell:AddToggle("bs_keepbig", { Text = L["Never Sell BIG and Up"], Default = true })
    Sell:AddToggle("bs_autosell", { Text = L["Auto Sell"], Default = false, Tooltip = L["Sells animals that match the rules above."] })
    Sell:AddButton({ Text = L["Sell Now"], Func = function()
        task.spawn(function()
            local n = sellSelected()
            notify(n > 0 and (L["Sold "] .. n .. L[" animals"]) or L["Nothing to sell"])
        end)
    end })

    task.spawn(function()
        local t = { eq = 0, idx = 0, sell = 0 }
        while RUNNING do
            local now = os.clock()
            if on("bs_equipbest") and now - t.eq > 4 then t.eq = now fire("PetsInventoryRemote", "EquipBest", nil) end
            if on("bs_index") and now - t.idx > 20 then t.idx = now fire("IndexRemote", "ClaimAll", nil) end
            if on("bs_autosell") and now - t.sell > 5 then t.sell = now pcall(sellSelected) end
            pcall(function()
                local plot = myPlot()
                petStatus:SetText(string.format(L["Plot %s/%s  ·  Bag %d\n%s cash/s"],
                    tostring(plot and plot:GetAttribute("AnimalsPlaced") or "?"),
                    tostring(plot and plot:GetAttribute("MaxAnimals") or "?"),
                    #animalTools(), abbrev(attr("CashPerSecond"))))
            end)
            task.wait(0.5)
        end
    end)
end)

section(L["Progress"], function()
    local function tierList()
        return (M.Pickaxe and type(M.Pickaxe.Tiers) == "table") and M.Pickaxe.Tiers or {}
    end
    local function trailList()
        return (M.Trails and type(M.Trails.Trails) == "table") and M.Trails.Trails or {}
    end
    local function buyPickaxe()
        local tiers = tierList()
        local cash = num(attr("Cash"))
        local owned = parseIds(attr("OwnedPickaxes"))
        local cur = num(attr("PickaxeTier"))
        local nxt = cur + 1
        local info = tiers[nxt]
        if info and not owned[nxt] and num(info.Price) <= cash then
            fire("PickaxeShopRequest", "Buy", nxt)
            task.wait(0.4)
            owned = parseIds(attr("OwnedPickaxes"))
        end
        local best = cur
        for id in pairs(owned) do if id > best then best = id end end
        if best > cur then fire("PickaxeShopRequest", "Equip", best) end
    end
    local function buyTrail()
        local list = trailList()
        local cash = num(attr("Cash"))
        local owned = parseIds(attr("OwnedTrails"))
        local equipped = num(attr("EquippedTrail"))
        local ownedBest = 0
        for _, tr in ipairs(list) do
            local id = tonumber(tr.Id)
            if id and owned[id] then ownedBest = math.max(ownedBest, num(tr.Multiplier)) end
        end
        local buy, buyMult = nil, ownedBest
        for _, tr in ipairs(list) do
            local id = tonumber(tr.Id)
            if id and not owned[id] and num(tr.Price) <= cash and num(tr.Multiplier) > buyMult then buy, buyMult = id, num(tr.Multiplier) end
        end
        if buy then
            fire("TrailShopRequest", "Buy", buy)
            task.wait(0.4)
            owned = parseIds(attr("OwnedTrails"))
        end
        local best, bestMult = nil, -1
        for _, tr in ipairs(list) do
            local id = tonumber(tr.Id)
            if id and owned[id] and num(tr.Multiplier) > bestMult then best, bestMult = id, num(tr.Multiplier) end
        end
        if best and best ~= equipped then fire("TrailShopRequest", "Equip", best) end
    end
    local function myTreadmill()
        local plot = myPlot()
        if not plot then return nil end
        for _, ch in ipairs(plot:GetChildren()) do
            if ch:IsA("Model") and ch.Name:lower():find("treadmill") then
                local hb = ch:FindFirstChild("Hitbox", true)
                if hb and hb:IsA("BasePart") then return hb end
            end
        end
    end

    local U = Tabs.Progress:AddLeftGroupbox(L["Upgrades"], "arrow-up")
    U:AddToggle("bs_pickaxe", { Text = L["Auto Buy Pickaxe"], Default = false, Tooltip = L["Buys and equips the next pickaxe."] })
    U:AddToggle("bs_trail", { Text = L["Auto Buy Trail"], Default = false, Tooltip = L["Buys and equips better trails."] })
    U:AddToggle("bs_plot", { Text = L["Auto Upgrade Plot"], Default = false })
    U:AddToggle("bs_treadup", { Text = L["Auto Upgrade Treadmill"], Default = false, Tooltip = L["Unlocks it first if needed."] })
    local upStatus = U:AddLabel(L["Pickaxe: -"], true)

    local T = Tabs.Progress:AddRightGroupbox(L["Speed Training"], "dumbbell")
    T:AddToggle("bs_train", { Text = L["Auto Train"], Default = false, Tooltip = L["Trains Speed on your treadmill. Pauses while farming."] })
    local trainStatus = T:AddLabel(L["Speed: -"], true)

    task.spawn(function()
        local t = { pk = 0, tr = 0, plot = 0, tm = 0 }
        while RUNNING do
            local now = os.clock()
            local tut = attr("TutorialActive") == true
            if not tut then
                if on("bs_pickaxe") and now - t.pk > 2 then t.pk = now pcall(buyPickaxe) end
                if on("bs_trail") and now - t.tr > 2 then t.tr = now pcall(buyTrail) end
                local cash = num(attr("Cash"))
                local plot = myPlot()
                if on("bs_plot") and plot and now - t.plot > 1 then
                    local ok, cost = gcall(M.PlotUp and M.PlotUp.UpgradeCost, plot:GetAttribute("PlotLevel"))
                    if not ok or (type(cost) == "number" and cash >= cost) then
                        t.plot = now
                        fire("UpgradePlotRequest")
                    end
                end
                if on("bs_treadup") and plot and now - t.tm > 1 then
                    if plot:GetAttribute("TreadmillUnlocked") == false then
                        if cash >= 100 then t.tm = now fire("UnlockTreadmillRequest") end
                    else
                        local ok, cost = gcall(M.TreadUp and M.TreadUp.UpgradeCost, plot:GetAttribute("TreadmillLevel"))
                        if not ok or (type(cost) == "number" and cash >= cost) then
                            t.tm = now
                            fire("UpgradeTreadmillRequest")
                        end
                    end
                end
            end
            pcall(function()
                local tiers = tierList()
                local cur = num(attr("PickaxeTier"))
                local nxt = tiers[cur + 1]
                local plot = myPlot()
                upStatus:SetText(string.format(L["%s%s\nPlot Lv %s  ·  Treadmill Lv %s%s"],
                    tostring(tiers[cur] and tiers[cur].Name or cur),
                    nxt and ("\nNext pickaxe: " .. abbrev(nxt.Price)) or "  (max)",
                    tostring(plot and plot:GetAttribute("PlotLevel") or "?"),
                    tostring(plot and plot:GetAttribute("TreadmillLevel") or "?"),
                    tut and "\nFinish tutorial first" or ""))
            end)
            task.wait(0.5)
        end
    end)
    task.spawn(function()
        while RUNNING do
            if on("bs_train") and not S.busy and not S.farming() and carrying() == 0 then
                local pad = myTreadmill()
                local r = root()
                if pad and r and (Vector3.new(r.Position.X, 0, r.Position.Z) - Vector3.new(pad.Position.X, 0, pad.Position.Z)).Magnitude > math.max(pad.Size.X, pad.Size.Z) / 2 then
                    tp(pad.Position + Vector3.new(0, pad.Size.Y / 2 + 3, 0))
                end
            end
            pcall(function()
                local mult = num(attr("SpeedBoostMultiplier"))
                trainStatus:SetText(L["Speed: "] .. abbrev(attr("SpeedPower")) .. (mult > 1 and (L["   Boost x"] .. mult) or "") .. (myTreadmill() and "" or L["\nUnlock your treadmill first"]))
            end)
            task.wait(1)
        end
    end)
end)

section(L["Rewards"], function()
    local function claimAll()
        fire("OfflineRewardRemote", "Claim")
        fire("GroupRewardRemote", "Claim")
        fire("IndexRemote", "ClaimAll", nil)
    end
    local R = Tabs.Rewards:AddLeftGroupbox(L["Rewards"], "gift")
    R:AddToggle("bs_autoclaim", { Text = L["Auto Claim Rewards"], Default = false, Tooltip = L["Claims free rewards."] })
    R:AddButton({ Text = L["Claim All Now"], Func = function() claimAll() notify(L["Claimed everything available"]) end })
    task.spawn(function()
        local last = -1e9
        while RUNNING do
            if on("bs_autoclaim") and os.clock() - last > 30 then last = os.clock() pcall(claimAll) end
            task.wait(1)
        end
    end)
end)

local antiAfkCon
local function setAntiAfk(v)
    if getconnections then
        for _, c in ipairs(getconnections(lp.Idled)) do pcall(function() c:Disconnect() end) end
    end
    if antiAfkCon then antiAfkCon:Disconnect() antiAfkCon = nil end
    if not v then return end
    antiAfkCon = track(lp.Idled:Connect(function()
        VirtualUser:CaptureController()
        VirtualUser:ClickButton2(Vector2.zero)
    end))
end

local PlayerBox = Tabs.Settings:AddLeftGroupbox(L["Player"], "user")
PlayerBox:AddToggle("bs_ws", { Text = L["Custom WalkSpeed"], Default = false })
PlayerBox:AddSlider("bs_wsval", { Text = "WalkSpeed", Default = 100, Min = 16, Max = 500, Rounding = 0, Tooltip = L["Higher helps outrun guards."] })
PlayerBox:AddToggle("bs_antiafk", { Text = L["Anti Idle"], Default = true, Callback = setAntiAfk })
PlayerBox:AddButton({ Text = L["TP To Base"], Func = function()
    local cf = bankCF()
    if cf then tp(cf) end
end })
local function applyWS()
    if not on("bs_ws") then return end
    local h = hum()
    if h and h.WalkSpeed ~= Opt.bs_wsval.Value then h.WalkSpeed = Opt.bs_wsval.Value end
end
local wsConn
local function hookWS(char)
    if wsConn then wsConn:Disconnect() wsConn = nil end
    local h = char and char:WaitForChild("Humanoid", 10)
    if not h then return end
    wsConn = track(h:GetPropertyChangedSignal("WalkSpeed"):Connect(function() task.defer(applyWS) end))
    applyWS()
end
track(lp.CharacterAdded:Connect(hookWS))
if lp.Character then task.spawn(hookWS, lp.Character) end
Opt.bs_wsval:OnChanged(applyWS)
task.spawn(function()
    while RUNNING do
        pcall(applyWS)
        task.wait(0.5)
    end
end)

local ServerBox = Tabs.Settings:AddLeftGroupbox(L["Server"], "server")
ServerBox:AddButton({ Text = L["Rejoin"], Func = function()
    pcall(function() TeleportService:TeleportToPlaceInstance(game.PlaceId, game.JobId, lp) end)
end })
ServerBox:AddButton({ Text = L["Server Hop"], Func = function()
    task.spawn(function()
        local ok, body = pcall(function()
            return game:HttpGet("https://games.roblox.com/v1/games/" .. game.PlaceId .. "/servers/Public?sortOrder=Asc&limit=100")
        end)
        if not ok then notify(L["Couldn't load servers"]) return end
        local dok, data = pcall(function() return HttpService:JSONDecode(body) end)
        if not dok or type(data) ~= "table" or type(data.data) ~= "table" then notify(L["Couldn't load servers"]) return end
        for _, s in ipairs(data.data) do
            if s.id ~= game.JobId and num(s.playing) < num(s.maxPlayers) then
                pcall(function() TeleportService:TeleportToPlaceInstance(game.PlaceId, s.id, lp) end)
                return
            end
        end
        notify(L["No other servers found"])
    end)
end })

